"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["41298"],{23136(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.formatos_permitidos.forma_invalida","status":422,"titulo":"FormatosPermitidos deve ser o token QUALQUER ou um array de formatos"},"descricao":{"codigo":"uniplus.selecao.formatos_permitidos.forma_invalida","requisitos":["UNI-REQ-0066"],"oQueAconteceu":["`formatosPermitidos` aceita duas formas: o texto `QUALQUER` ou uma lista de formatos. A exig\xeancia\\nenviada trouxe outra coisa. S\xe3o recusados:","- um valor que n\xe3o \xe9 texto nem lista (por exemplo, um n\xfamero ou um objeto);\\n- um texto diferente de `QUALQUER`, com a grafia exata em mai\xfasculas;\\n- um item da lista que n\xe3o \xe9 texto nem objeto com `formato` e `tamanhoMaximoBytesMax`;\\n- um item em forma de objeto sem `formato` em texto;\\n- um `tamanhoMaximoBytesMax` presente que n\xe3o \xe9 um n\xfamero inteiro.","Cada item da lista \xe9 um texto (por exemplo, `PDF`, sem limite pr\xf3prio) ou um objeto com `formato` e,\\nopcionalmente, `tamanhoMaximoBytesMax`. A mensagem de detalhe diz qual dessas formas foi recusada.","A confer\xeancia acontece na montagem de cada exig\xeancia, depois das confer\xeancias do tipo de\\ndocumento, das condi\xe7\xf5es e das bases legais, e depois da idade m\xe1xima de emiss\xe3o; a do modelo\\ncitado vem em seguida. A confer\xeancia registra as recusas das regras informadas. A aus\xeancia do campo\\n\xe9 outra causa\\n([`obrigatorio`](/erros/uniplus.selecao.formatos_permitidos.obrigatorio)), e um item de texto que n\xe3o\\n\xe9 um formato conhecido tamb\xe9m\\n([`formato_invalido`](/erros/uniplus.selecao.formatos_permitidos.formato_invalido))."],"comoResolver":["Declare `formatosPermitidos` como o texto `QUALQUER` ou como uma lista em que cada item \xe9 um texto\\ncom o formato ou um objeto `{ \\"formato\\": \\"PDF\\", \\"tamanhoMaximoBytesMax\\": 1048576 }`. O limite\\n`tamanhoMaximoBytesMax`, quando presente, \xe9 um n\xfamero inteiro. Depois, envie a defini\xe7\xe3o de novo."],"ondeAparece":["Defini\xe7\xe3o de documentos exigidos do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Formatos permitidos"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);